// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set initial betLimit to 100 via constructor (wagerLimit = 100)
        // Deploy with wagerLimit=100: c = new C(address(this), 100);
        // Actually, setUp uses 0, so we need to adjust: redeploy with 100
        // To avoid changing setUp, we call AdjustBetAmounts first to set to 100
        // But AdjustBetAmounts in reference sets = amount, so we call it with 100
        vm.prank(address(this));
        c.AdjustBetAmounts(100); // now betLimit = 100 in reference, 0*100=0? Wait, initial is 0, so *= gives 0.
        // Actually need to start from non-zero. Better: deploy in test with wagerLimit=100.
        // Since we cannot change setUp, we must redeploy in test.
        // But rule says "Deploy in setUp() using the given new C(address(this), 0) verbatim." So we must keep setUp as is.
        // Then initial betLimit = 0. Then AdjustBetAmounts(100) yields reference: 100, bug: 0*100=0.
        // That fails to show difference because bug also sets to 0. So instead of that, we note that the test can use vm.prank to call AdjustBetAmounts(2) after first setting betLimit to 100 via a separate call? But reference sets =, so we can set to 100 by calling AdjustBetAmounts(100). But bug *= gives 0. So after that, betLimit is either 100 (ref) or 0 (bug). Then call AdjustBetAmounts(2): ref = 2, bug = 0*2 = 0. Assert c.betLimit() == 2 gives ref pass, bug fail.
        // That works! So sequence: 
        // 1. AdjustBetAmounts(100) -> ref: 100, bug: 0
        // 2. AdjustBetAmounts(2)   -> ref: 2, bug: 0*2 = 0
        // assert c.betLimit() == 2 -> ref true, bug false.
        // But need only owner: setUp deploys with address(this) as owner.
        vm.prank(address(this));
        c.AdjustBetAmounts(100);
        vm.prank(address(this));
        c.AdjustBetAmounts(2);
        assertTrue(c.currentBetLimit() == 2);
    }
}

