pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set up: deployer (this) is owner, open to public, set betLimit to 5 ether
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustBetAmounts(5 ether);

        // Create a player account and fund it
        address player = address(0x1234);
        vm.deal(player, 10 ether);

        // Player wagers 5 ether (the exact betLimit) — works in both versions
        vm.prank(player);
        c.wager{value: 5 ether}();

        // Player sends extra 5 ether via fallback to pump contract balance (buggy allows this; reference does not enforce after wager, but buggy's wager() miss-bypasses msg.value check — however fallback is allowed in both)
        vm.prank(player);
        (bool okFallback,) = address(c).call{value: 5 ether}("");
        require(okFallback, "fallback failed");

        // Advance one block so play() can proceed
        vm.roll(block.number + 1);

        // Player calls play(); in reference, payout sends half of current balance; in buggy, same but the balance differs because wager() allowed different amounts? Actually both wagers were 5 ether. To exploit the missing require, we need a different scenario: after setting betLimit to 5 ether, another player wagers with msg.value != betLimit in buggy version but reference reverts. Let's instead choose: set betLimit = 1 ether, then player wagers 2 ether (no require in M). So contract balance increases differently.
        // Correct approach: 
        vm.prank(player);
        c.play();

        // After play, the contract's balance should be halved. But the bug's wager allowed extra ether? Actually the bug only removes the msg.value == betLimit check. So a player could wager 2 ether when betLimit is 1 ether. Let's reset and do that concretely.
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Open to public and set betLimit
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustBetAmounts(2 ether);

        // Actor with 2 ether
        address actor = address(0x1234);
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        // In reference: require(msg.value == betLimit) -> succeeds with 2 ether
        // In buggy: no require -> succeeds regardless
        // But we need a scenario where they diverge: reference succeeds, buggy reverts? No, buggy allows all, so reference reverts on != betLimit.
        // Actually, let's check: reference reverts if msg.value != betLimit, so call with 2 ether succeeds; buggy also succeeds. Divergence not here.
        // We need a value that causes reference to revert and buggy to succeed.
        vm.prank(actor);
        // try-catch to catch revert
        bool refSucceeded;
        try c.wager{value: 3 ether}() {
            refSucceeded = true;
        } catch {
            refSucceeded = false;
        }
