pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // No set-up needed: difficulty is 0 by default, so adjust betLimit then check difficulty
        c.AdjustBetAmounts(20);
        // In reference, currentDifficulty() returns the stored difficulty (initially 0 after adjust? Actually AdjustBetAmounts does not change difficulty, so difficulty remains 0).
        // But the bug always returns 0, so the assertion below would pass on both. We need a scenario where difficulty is non-zero.
        // Let's instead set difficulty first via AdjustDifficulty.
        c.AdjustDifficulty(5);
        c.AdjustBetAmounts(20);
        // Now reference should return 5, bug returns 0.
        assertTrue(c.currentDifficulty() == 5);
    }
}

