pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Open to public
        c.OpenToThePublic();
        // Set difficulty so that winningNumber == difficulty/2 is guaranteed
        c.AdjustDifficulty(2); // difficulty = 2, winningNumber range 1-2, difficulty/2 = 1
        // Set betLimit to 100
        c.AdjustBetAmounts(100);
        // Fund player
        address player = address(0x1234);
        vm.deal(player, 100 ether);
        // Player wagers exactly 100 wei (payable uses wei, 100 = 100 wei)
        vm.prank(player);
        c.wager{value: 100}();
        // contract balance now = 100
        // Play - since difficulty=2 and random seed is 0, keccak256 will produce some number mod 2 + 1; with seed=0, blockhash, it might not be 1. But we can instead directly call winnersPot() before play, because the bug is in winnersPot() only.
        // Actually, the test just needs winnersPot() to return different values – no need to trigger play().
        // Deploy a new scenario: after wager, contract balance = 100. winnersPot() returns 50 (correct) vs 25 (bug).
        uint256 correctValue = address(c).balance / 2;
        uint256 actualValue = c.winnersPot();
        assertTrue(actualValue == correctValue, "winnersPot should return balance/2");
    }
}

