pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set betLimit to 100
        c.AdjustBetAmounts(100);
        // Make contract open to public
        c.OpenToThePublic();
        // Fund a player
        address player = address(0x1234);
        vm.deal(player, 100);
        vm.prank(player);
        c.wager{value: 100}();
        // Fast-forward one block so play can succeed
        vm.roll(block.number + 1);
        // Play to trigger payout (player wins or loses — balance changes)
        vm.prank(player);
        c.play();
        // Now contract balance is 100 (original 200 minus 100 sent to whale via loseWager)
        // winnersPot returns balance/2 = 50 in reference, balance/4 = 25 in bug
        assertTrue(c.winnersPot() == 50);
    }
}

