        vm.deal(address(this), 300);
        (bool sent, ) = address(c).call{value: 200}("");
        require(sent);
        // Wager from a different address
        address player = address(0x1);
        vm.deal(player, 100);
        vm.prank(player);
        c.wager{value: 100}();
        // Play — this will send 50 to whale (this) and 50 to winner, leaving 200 from funding
        vm.prank(player);
        c.play();
        // Now contract balance = 200, so winnersPot() = 100 in correct, 50 in bug
        uint256 pot = c.winnersPot();
        assertTrue(pot == 100, "winnersPot should be 100 in reference");
    }
}

