pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Setup: owner opens to public, sets betLimit and difficulty
        vm.startPrank(address(this));
        c.OpenToThePublic();
        c.AdjustBetAmounts(100);
        c.AdjustDifficulty(2);
        vm.stopPrank();

        // Fund contract with extra 200 wei (total balance 200) before wager
        vm.deal(address(this), 200);
        (bool success,) = address(c).call{value: 200}("");
        require(success, "fund failed");

        // Player wagers 100
        address player = address(0x1234);
        vm.deal(player, 100);
        vm.prank(player);
        c.wager{value: 100}();

        // Player plays (must be tx.origin == msg.sender)
        vm.prank(player);
        c.play();

        // After play, contract balance = 200 (initial) + 100 (wager) - 50 (to winner) - 50 (to whale) = 200
        // But we need non-zero balance for winnersPot to differ
        // Actually balance = 200 + 100 - 50 - 50 = 200
        // winnersPot() = 200/2 = 100 (reference) vs 200/4 = 50 (bug)
        uint256 result = c.winnersPot();
        assertTrue(result == 100, "winnersPot should be 100 in reference");
    }
}

