pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Open to public
        c.OpenToThePublic();
        // Set bet limit to 100 wei
        c.AdjustBetAmounts(100);
        // Set difficulty to 4 so that winningNumber == difficulty/2 (2) is possible
        c.AdjustDifficulty(4);
        // Fund a player account with 100 wei
        address player = address(0x1234);
        vm.deal(player, 100);
        vm.prank(player);
        c.wager{value: 100}();
        // Player plays (we need block.number > block where wager placed, so warp forward)
        vm.roll(block.number + 1);
        vm.prank(player);
        c.play();
        // After play, contract balance is 0 (half sent to winner, half to whale)
        // Now fund contract with 100 wei directly
        vm.deal(address(this), 100);
        payable(address(c)).transfer(100);
        // Now contract balance is 100, so winnersPot() should return 50 in reference, 25 in bug
        uint256 pot = c.winnersPot();
        // Reference: balance/2 = 50, bug: balance/4 = 25
        assertTrue(pot == 50, "winnersPot should be 50 in reference");
    }
}
